// P2-existing: read an MKVToolNix-authored source with an attachment-UID
// targeted Tag and a decoy attachment. Confirm edit intents refuse writing.
// No output container is ever generated by this research check.
import fs from 'node:fs/promises';
import path from 'node:path';
import { createHash } from 'node:crypto';
import { execFileSync } from 'node:child_process';
import { createMatroskaAttachmentReader } from '../src/matroska-attachment-reader.js';
import { createExistingAttachmentEditIntent } from '../src/existing-attachment-edit-intent.js';
import { parseMkvmergeJsonWithExactUids, exactPositiveUid } from '../src/mkvmerge-exact-uid-json.js';

const fixtureDir = path.resolve(process.env.E2E_FIXTURE_DIR || '.e2e/fixtures');
const outputDir = path.resolve(process.env.E2E_OUTPUT_DIR || '.e2e/output');
const sourcePath = path.join(fixtureDir, 'p0-independent-attachmenttag.mkv');
const reportPath = path.join(outputDir, 'p2-existing-attachment-edit-block-report.json');
const hash = value => createHash('sha256').update(value).digest('hex');
const report = {
  schema: 'p2-existing-attachment-edit-preflight-audit-v0',
  result: 'INCONCLUSIVE',
  sourceAuthoredWith: 'independent-MKVToolNix',
  modificationExecuted: false,
  generatedMkv: false,
  writer: null,
};
await fs.mkdir(outputDir, { recursive: true });
try {
  const bytes = await fs.readFile(sourcePath);
  const originalHash = hash(bytes);
  const file = new Blob([bytes], { type: 'application/octet-stream' });
  file.name = path.basename(sourcePath);
  file.lastModified = 123;
  report.originalSha256 = originalHash;
  const source = parseMkvmergeJsonWithExactUids(execFileSync('mkvmerge', ['-J', sourcePath], {
    encoding: 'utf8', timeout: 30000,
  }));
  const attachments = source.attachments || [];
  if (attachments.length !== 2) throw new Error('P0_INDEPENDENT_ATTACHMENT_COUNT_UNEXPECTED');
  report.independentAttachments = attachments.map(a => ({
    name: a.file_name, uid: exactPositiveUid(a.properties?.uid),
  }));
  const evidence = attachments.find(x => x.file_name === 'p0-attachment-evidence.bin');
  const decoy = attachments.find(x => x.file_name === 'p0-attachment-decoy.txt');
  if (!evidence || !decoy ||
      exactPositiveUid(evidence.properties?.uid) === exactPositiveUid(decoy.properties?.uid)) {
    throw new Error('P0_ATTACHMENT_UID_PROVENANCE_MISSING');
  }

  const reader = createMatroskaAttachmentReader(file);
  const readOnly = await createExistingAttachmentEditIntent({ reader });
  report.readOnlyCapability = readOnly.capability.code;
  const target = readOnly.proposedChanges.effects.find(x =>
    x.originalFilename === 'p0-attachment-evidence.bin');
  if (!target || target.sourceFileUid !== String(evidence.properties.uid)) {
    throw new Error('MODEL_SOURCE_UID_MISMATCH');
  }
  const removed = await createExistingAttachmentEditIntent({
    reader, actions: [{ type: 'remove',
      attachmentId: target.sourceAttachmentId }],
  });
  const replacement = new Blob([Buffer.from('replacement is never written')]);
  replacement.name = 'replacement.txt';
  replacement.lastModified = 321;
  const replaced = await createExistingAttachmentEditIntent({
    reader, actions: [{ type: 'replace',
      attachmentId: target.sourceAttachmentId,
      file: replacement, mimeType: 'text/plain' }],
  });
  report.sourcePreservation = removed.preservationPreflight;
  report.removeCapability = removed.capability;
  report.replaceCapability = replaced.capability;
  report.sourceAttachmentCount = removed.sourceObservation.sourceAttachmentCount;
  report.unchangedDecoy = removed.proposedChanges.effects.some(x =>
    x.originalFilename === 'p0-attachment-decoy.txt' && x.action === 'retain' &&
    x.sourceFileUid === String(decoy.properties.uid));
  if (!report.unchangedDecoy || removed.execution.approvedToWrite ||
      replaced.execution.approvedToWrite ||
      removed.capability.code !== 'SOURCE_UID_RELATIONS_UNVERIFIED' ||
      replaced.capability.code !== 'SOURCE_UID_RELATIONS_UNVERIFIED') {
    throw new Error('P0_UID_TARGETED_ATTACHMENT_MUTATION_NOT_BLOCKED');
  }
  report.afterSha256 = hash(await fs.readFile(sourcePath));
  if (report.afterSha256 !== originalHash) {
    throw new Error('P0_SOURCE_MODIFIED_DURING_DRAFTING');
  }
  report.result = 'UID_TAGGED_EXISTING_ATTACHMENT_EDIT_BLOCKED_SOURCE_UNCHANGED';
} catch (error) {
  report.result = 'INCONCLUSIVE_OR_FAILED';
  report.error = error?.message || String(error);
} finally {
  await fs.writeFile(reportPath, JSON.stringify(report, null, 2) + '\n');
  console.log(JSON.stringify({
    result: report.result,
    error: report.error || null,
    removeCode: report.removeCapability?.code,
    replaceCode: report.replaceCapability?.code,
    reportPath,
  }));
}
if (report.result !== 'UID_TAGGED_EXISTING_ATTACHMENT_EDIT_BLOCKED_SOURCE_UNCHANGED') {
  process.exitCode = 1;
}
